package com.testgen.api.controller;
import com.testgen.api.entity.*; import com.testgen.api.repository.*; import com.testgen.api.service.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*; import java.util.zip.*;
@RestController @RequestMapping("/api/projects") @CrossOrigin(origins="*") public class ProjectController { private final ProjectService service; private final ProjectRepository projects; private final TestCaseRepository tests; private final AnalysisResultRepository analyses; private final HttpService http; private final String analysisUrl; private final String executionUrl; private final Path root=Paths.get("/workspace");
 public ProjectController(ProjectService s,ProjectRepository p,TestCaseRepository t,AnalysisResultRepository a,HttpService h,@org.springframework.beans.factory.annotation.Value("${app.analysis-url}")String au,@org.springframework.beans.factory.annotation.Value("${app.execution-url}")String eu){service=s;projects=p;tests=t;analyses=a;http=h;analysisUrl=au;executionUrl=eu;}
 @GetMapping public List<Project> all(java.security.Principal p){return service.all(p.getName());}
 @PostMapping public Project create(java.security.Principal u,@RequestBody Project p){return service.create(u.getName(),p);}
 @GetMapping("/{id}") public Project get(@PathVariable Long id){return service.get(id);}
 @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}
 @PostMapping("/{id}/upload") public Map<String,Object> upload(@PathVariable Long id,@RequestParam MultipartFile file)throws Exception{Project p=service.get(id);Path dir=root.resolve("project-"+id);Files.createDirectories(dir);String n=Path.of(Objects.requireNonNull(file.getOriginalFilename())).getFileName().toString();Path target=dir.resolve(n);file.transferTo(target);int extracted=0;if(n.toLowerCase().endsWith(".zip")){extracted=extractZip(target,dir);}return Map.of("projectId",id,"file",n,"path",target.toString(),"status","UPLOADED","extractedFiles",extracted);}
 private int extractZip(Path zipFile,Path destDir)throws java.io.IOException{int count=0;try(ZipInputStream zis=new ZipInputStream(Files.newInputStream(zipFile))){ZipEntry entry;while((entry=zis.getNextEntry())!=null){Path resolved=destDir.resolve(entry.getName()).normalize();if(!resolved.startsWith(destDir))continue;if(entry.isDirectory()){Files.createDirectories(resolved);}else{if(resolved.getParent()!=null)Files.createDirectories(resolved.getParent());Files.copy(zis,resolved,StandardCopyOption.REPLACE_EXISTING);count++;}zis.closeEntry();}}return count;}
 @PostMapping("/{id}/analyze") public String analyze(@PathVariable Long id){Project p=service.get(id);return http.post(analysisUrl,"/analyze/project",Map.of("projectId",id,"path","/workspace/project-"+id,"language",p.language==null?"Java":p.language));}
 @PostMapping("/{id}/generate-tests") public String generate(@PathVariable Long id){Project p=service.get(id);return http.post(analysisUrl,"/generate/tests",Map.of("projectId",id,"path","/workspace/project-"+id,"language",p.language==null?"Java":p.language));}
 @PostMapping("/{id}/run-tests") public String run(@PathVariable Long id){Project p=service.get(id);return http.post(executionUrl,"/run",Map.of("projectId",id,"path","/workspace/project-"+id,"language",p.language==null?"Java":p.language));}
 @GetMapping("/{id}/test-cases") public List<TestCase> testCases(@PathVariable Long id){return tests.findAll().stream().filter(t->t.project.id.equals(id)).toList();}
 @GetMapping("/{id}/analysis") public List<AnalysisResult> analysis(@PathVariable Long id){return analyses.findAll().stream().filter(a->a.project.id.equals(id)).toList();}
}
